=== src/frontend/src/lib/useLoad.ts
     1	"use client";
     2	
     3	import { useEffect, useState } from "react";
     4	
     5	// Lädt Daten für einen Schlüssel (z. B. Szenario-ID) und liefert data/error/loading.
     6	// loading wird aus dem Schlüssel abgeleitet, so braucht es kein setState im Effect.
     7	export function useLoad<T>(key: string, fetcher: () => Promise<T>) {
     8	  const [state, setState] = useState<{ key: string; data: T | null; error: string | null }>({ key: "", data: null, error: null });
     9	
    10	  useEffect(() => {
    11	    let cancelled = false;
    12	    fetcher()
    13	      .then((data) => !cancelled && setState({ key, data, error: null }))
    14	      .catch((e: Error) => !cancelled && setState({ key, data: null, error: e.message }));
    15	    return () => {
    16	      cancelled = true;
    17	    };
    18	    // fetcher ist pro key stabil gedacht, darum hängt der Effect nur am Schlüssel.
    19	    // eslint-disable-next-line react-hooks/exhaustive-deps
    20	  }, [key]);
    21	
    22	  const ready = state.key === key;
    23	  return { data: ready ? state.data : null, error: ready ? state.error : null, loading: !ready };
    24	}
=== src/frontend/src/lib/conflicts.ts
     1	// Widersprüche einer Anforderung, gleiche Regel wie die Detailseite (core/views.py explain):
     2	// nur Paare, bei denen BEIDE Befunde zitiert sind. Sonst zeigt die Liste ein "!", die Detailseite aber nichts.
     3	type ConflictSignal = { id: string; title: string; conflicts_with: string[] };
     4	
     5	export function conflictTitlesFor(signalIds: string[], signalById: Map<string, ConflictSignal>): string[] {
     6	  const cited = new Set(signalIds);
     7	  const pairs = new Set<string>();
     8	  for (const id of signalIds) {
     9	    for (const other of signalById.get(id)?.conflicts_with ?? []) {
    10	      if (cited.has(other)) pairs.add([id, other].sort().join("|"));
    11	    }
    12	  }
    13	  return [...pairs].sort().map((pair) => {
    14	    const [a, b] = pair.split("|");
    15	    return `${signalById.get(a)?.title ?? a} ↔ ${signalById.get(b)?.title ?? b}`;
    16	  });
    17	}
=== src/frontend/app/page.tsx
     1	import { readdir } from "node:fs/promises";
     2	import path from "node:path";
     3	import { HomePage } from "@/src/components/home/HomePage";
     4	
     5	// Listet vorhandene Bilder in public/media (z. B. /media/poster.jpg), damit fehlende Medien keinen 404 auslösen.
     6	async function listMedia(dir = ""): Promise<string[]> {
     7	  const root = path.join(process.cwd(), "public", "media", dir);
     8	  try {
     9	    const entries = await readdir(root, { withFileTypes: true });
    10	    const nested = await Promise.all(
    11	      entries.map(async (e) =>
    12	        e.isDirectory() ? (e.name === "car" ? [] : listMedia(path.join(dir, e.name))) : [`/media/${path.posix.join(dir.replaceAll("\\", "/"), e.name)}`],
    13	      ),
    14	    );
    15	    return nested.flat();
    16	  } catch {
    17	    return [];
    18	  }
